import bundle from "../content/bundle.json" with { type: "json" };

/** Generated by scripts/build-content.mjs; see that file for the source layout. */
export type Skill = {
  name: string;
  description: string;
  kind: "instruction" | "script" | "hybrid" | "resource";
  tag: "faceless" | "branded" | "talking_head" | "universal";
  category: string;
  script?: string;
  requires?: string[];
  inputs?: string;
  outputs?: string;
  schema_refs?: string[];
  body: string;
  files: string[];
  file_contents: Record<string, string>;
};

export type Recipe = { name: string; title: string; description: string; args?: Record<string, string>; body: string };
export type Pack = { manifest: Record<string, unknown> & { pack_id: string; name?: string; description?: string; version: string }; files: string[]; file_contents: Record<string, string> };

export type Bundle = {
  version: number;
  skills: Record<string, Skill>;
  schemas: Record<string, unknown>;
  data: Record<string, unknown>;
  asset_sources: Record<string, unknown>;
  registry: Record<string, Array<Record<string, unknown> & { id: string; name: string; category: string }>>;
  rulebooks: Record<string, Record<string, string>>;
  recipes: Record<string, Recipe>;
  packs: Record<string, Pack>;
  toolkit: { files: string[]; file_contents: Record<string, string> };
};

export const content = bundle as unknown as Bundle;

export const SKILL_CATEGORIES = ["strategy", "script", "scene", "design", "motion", "audio", "captions", "footage", "image", "assets", "render", "quality", "workflow", "orchestration"] as const;
export const SKILL_TAGS = ["faceless", "branded", "talking_head", "universal"] as const;
export const SKILL_KINDS = ["instruction", "script", "hybrid", "resource"] as const;

export function skillSummary(s: Skill) {
  return { name: s.name, description: s.description, kind: s.kind, tag: s.tag, category: s.category, script: s.script ?? null, files: s.files };
}

/** Plain keyword scoring over name, description and body: name hits weigh most. */
export function searchSkills(query: string, limit = 10) {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  return Object.values(content.skills)
    .map((s) => {
      const name = s.name.toLowerCase(), desc = s.description.toLowerCase(), body = s.body.toLowerCase();
      let score = 0;
      for (const t of terms) {
        if (name.includes(t)) score += 5;
        if (desc.includes(t)) score += 2;
        if (body.includes(t)) score += 1;
      }
      return { skill: s, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((x) => ({ ...skillSummary(x.skill), score: x.score }));
}

export function skillText(s: Skill) {
  const header = [
    `# ${s.name}`,
    `kind: ${s.kind} | tag: ${s.tag} | category: ${s.category}${s.script ? ` | script: ${s.script}` : ""}`,
    s.inputs ? `inputs: ${s.inputs}` : null,
    s.outputs ? `outputs: ${s.outputs}` : null,
    s.requires?.length ? `requires: ${s.requires.join(", ")}` : null,
    s.files.length ? `files: ${s.files.join(", ")} (fetch with get_skill_file)` : null,
  ].filter(Boolean).join("\n");
  return `${header}\n\n${s.body}`;
}

/** Fill {{arg}} placeholders in a recipe body; unknown args keep the default text. */
export function renderRecipe(r: Recipe, args: Record<string, string | undefined>) {
  return r.body.replace(/\{\{(\w+)\}\}/g, (_, k: string) => args[k] ?? `(${k} not given)`);
}
